// chainMuteFixture opens a real store + module registry and the closure built
// over them (the openRegistry posture of the module package's own tests — the
// closure/store/registry joint runs on real instances, never a fake). The
// registry auto-seeds the tv/image/serial module configs, so the serial
// module's three-source chain (serial-parser, frame-grabber, shikimori — all
// enabled at seed) is the real served shape, and loadedCaps names all three
// metadata plugins as loaded (the refresh filter sees them all).
func chainMuteFixture(t *testing.T) (func(context.Context, string, int64) (api.ModulePresentation, error), *store.Store, *module.Registry) {
	t.Helper()
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "chainmute.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	closure := newModulePresentationClosure(st, reg, map[string][]string{
		"serial-parser": {"metadata_source"},
		"frame-grabber": {"metadata_source"},
		"shikimori":     {"metadata_source"},
	})
	return closure, st, reg
}

// chainEnabled maps a presentation's source_chain into id→enabled for
// order-and-verdict assertions.
func chainEnabled(p api.ModulePresentation) map[string]bool {
	m := make(map[string]bool, len(p.SourceChain))
	for _, src := range p.SourceChain {
		m[src.ID] = src.Enabled
	}
	return m
}

// TestChainMuteClosure pins task 10.1's client-facing mute projection: the
// ModulePresentation closure ANDs the request Viewer's ChainMutes down
// post-ResolveGates — a muted source's enabled=false lands in source_chain
// and drops from refresh_sources (the only client-facing lists this closure
// serves), while admin/System viewers and the bare-ctx degradation path see
// the unmutted verdict, and an operator library-row can never lift a group
// mute (the AND-down only mutes). Also pins the COPIES law: the module
// config's own bindings are never mutated by a projection call.
func TestChainMuteClosure(t *testing.T) {
	closure, st, reg := chainMuteFixture(t)
	ctx := context.Background()
	const libID = int64(7)
	const mutedSource = "shikimori" // serial chain: serial-parser, frame-grabber, shikimori

	// Baseline on the bare context (NO stashed viewer — access.FromContext
	// reads the zero Viewer): the full chain, all sources enabled, the loaded
	// shikimori present in title_sources and refresh_sources.
	bare, err := closure(ctx, "serial", libID)
	if err != nil {
		t.Fatalf("closure(bare ctx): %v", err)
	}
	if len(bare.SourceChain) != 3 {
		t.Fatalf("bare source_chain = %d entries, want 3", len(bare.SourceChain))
	}
	if bare.SourceChain[0].ID != "serial-parser" || bare.SourceChain[1].ID != "frame-grabber" || bare.SourceChain[2].ID != mutedSource {
		t.Fatalf("bare source_chain order = %v/%v/%v, want serial-parser/frame-grabber/shikimori",
			bare.SourceChain[0].ID, bare.SourceChain[1].ID, bare.SourceChain[2].ID)
	}
	for _, src := range bare.SourceChain {
		if !src.Enabled {
			t.Fatalf("bare source_chain %s disabled, want enabled (zero-Viewer degradation must be exactly today's behavior)", src.ID)
		}
	}
	if len(bare.RefreshSources) != 1 || bare.RefreshSources[0].ID != mutedSource || !bare.RefreshSources[0].Enabled {
		t.Fatalf("bare refresh_sources = %+v, want shikimori enabled", bare.RefreshSources)
	}
	if len(bare.TitleSources) != 1 || bare.TitleSources[0].ID != mutedSource || !bare.TitleSources[0].Enabled {
		t.Fatalf("bare title_sources = %+v, want shikimori enabled", bare.TitleSources)
	}

	muted := access.User(7, []int64{libID}, map[string]bool{mutedSource: true})
	mutedCtx := access.WithViewer(ctx, muted)

	// The muted viewer: shikimori flips enabled=false in source_chain ONLY
	// (the wire shape is unchanged — zero new fields), drops from
	// refresh_sources, and rides title_sources as disabled; the other chain
	// entries are untouched, and the parsers/identity block is identical.
	got, err := closure(mutedCtx, "serial", libID)
	if err != nil {
		t.Fatalf("closure(muted viewer): %v", err)
	}
	want := chainEnabled(bare)
	want[mutedSource] = false
	if gotChain := chainEnabled(got); len(gotChain) != len(want) {
		t.Fatalf("muted source_chain = %d entries, want %d", len(gotChain), len(want))
	} else {
		for id, wantEnabled := range want {
			if gotChain[id] != wantEnabled {
				t.Errorf("muted source_chain %s enabled = %v, want %v", id, gotChain[id], wantEnabled)
			}
		}
	}
	if len(got.RefreshSources) != 0 {
		t.Fatalf("muted refresh_sources = %+v, want empty (a muted source never serves as refreshable)", got.RefreshSources)
	}
	if len(got.TitleSources) != 1 || got.TitleSources[0].ID != mutedSource || got.TitleSources[0].Enabled {
		t.Fatalf("muted title_sources = %+v, want shikimori carried disabled", got.TitleSources)
	}
	if len(got.Parsers) != len(bare.Parsers) {
		t.Fatalf("muted parsers = %d entries, want %d (the parser bindings are never muted)", len(got.Parsers), len(bare.Parsers))
	}

	// Admin and System viewers (empty ChainMutes): identical to the bare
	// baseline — an unrestricted scope is never ANDed down.
	for name, v := range map[string]access.Viewer{
		"admin":  access.Admin(),
		"system": access.System(),
	} {
		p, err := closure(access.WithViewer(ctx, v), "serial", libID)
		if err != nil {
			t.Fatalf("closure(%s viewer): %v", name, err)
		}
		if gotChain := chainEnabled(p); len(gotChain) != 3 {
			t.Fatalf("%s source_chain = %d entries, want 3", name, len(gotChain))
		} else {
			for id, enabled := range gotChain {
				if !enabled {
					t.Errorf("%s source_chain %s disabled, want unaffected", name, id)
				}
			}
		}
		if len(p.RefreshSources) != 1 || p.RefreshSources[0].ID != mutedSource {
			t.Fatalf("%s refresh_sources = %+v, want shikimori (admin/System unaffected)", name, p.RefreshSources)
		}
	}

	// Operator library-row never lifts a group mute: seed the operator's
	// library-scope ENABLE row for the very source the group muted. The gate
	// resolution keeps the source enabled (a gate row can only mute) and the
	// viewer AND-down still mutes it for the muted viewer — while the clean
	// viewer keeps the enabled verdict.
	stamp := time.Now().UTC().Format(time.RFC3339Nano)
	if err := st.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
		ModuleID: "serial", LibraryID: libID, PluginID: mutedSource, Enabled: true, UpdatedAt: stamp,
	}); err != nil {
		t.Fatalf("seed operator enable row: %v", err)
	}
	clean, err := closure(ctx, "serial", libID)
	if err != nil {
		t.Fatalf("closure(clean viewer + operator row): %v", err)
	}
	if chain := chainEnabled(clean); !chain[mutedSource] {
		t.Fatalf("clean viewer with operator enable row: shikimori disabled, want the row carried (gate verdict only)")
	}
	lifted, err := closure(mutedCtx, "serial", libID)
	if err != nil {
		t.Fatalf("closure(muted viewer + operator row): %v", err)
	}
	if chain := chainEnabled(lifted); chain[mutedSource] {
		t.Fatalf("muted viewer with operator enable row: shikimori enabled, want the group mute to hold (AND-down can only mute)")
	}

	// COPIES law: the projection call mutated only its per-call copies — the
	// module config's own bindings still carry the seed verdict.
	fresh, err := reg.Get("serial")
	if err != nil {
		t.Fatalf("re-Get(serial): %v", err)
	}
	for _, src := range fresh.MetadataSources {
		if !src.Enabled {
			t.Errorf("module config binding %s mutated to disabled by the projection (copies law)", src.PluginID)
		}
	}
}

// TestDepsIdentityWired pins task 10.1's composition-root assignment: the
// service main() builds (newIdentityService over the store) is non-nil and
// LIVE over that store, and the api Deps field the composition root assigns
// (Deps.Identity) carries it — a nil Identity would silently legacy-fall
// EVERY principal at runtime.
func TestDepsIdentityWired(t *testing.T) {
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "identitywired.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })

	svc := newIdentityService(st)
	if svc == nil {
		t.Fatal("newIdentityService(st) = nil, want the accounts domain service (nil wiring would silently legacy-fall EVERY principal)")
	}
	// The Deps field 6.1 added is what the composition root assigns — the
	// wired Deps must carry the service, never nil.
	deps := api.Deps{Identity: svc}
	if deps.Identity == nil {
		t.Fatal("wired Deps.Identity = nil, want the identity service")
	}
	// Liveness over the REAL store the service was built on: HasUsers reads
	// the users table (false on the fresh store) and Create flips it — a
	// nil-wired or foreign-store service could not.
	users, err := svc.HasUsers(ctx)
	if err != nil {
		t.Fatalf("HasUsers on fresh store: %v", err)
	}
	if users {
		t.Fatal("HasUsers = true on a fresh store, want false")
	}
	if _, err := svc.Create(ctx, "operator", "correct horse battery staple"); err != nil {
		t.Fatalf("Create: %v", err)
	}
	users, err = svc.HasUsers(ctx)
	if err != nil {
		t.Fatalf("HasUsers after Create: %v", err)
	}
	if !users {
		t.Fatal("HasUsers = false after Create, want true (the service is not reading the store it was built over)")
	}
}
